SELECT  
        WHERE s.snap_id IN #{id}
        AND s.status=0 AND u.status=0 ORDER BY FIELD(s.snap_id,#{id})

SELECT  FROM snap s LEFT JOIN `user` u ON u.user_id=s.user_id


        AND (s.`desc` LIKE CONCAT('%',#{keyword},'%')
        OR u.name LIKE CONCAT('%',#{keyword},'%')
        OR u.major LIKE CONCAT('%',#{keyword},'%')
        OR CAST(s.snap_id AS CHAR) LIKE CONCAT('%',#{keyword},'%'))

    AND s.type=#{type}
    AND s.status=#{status}

ORDER BY s.snap_id DESC LIMIT #{offset},#{limit}

SELECT COUNT(1) FROM snap s LEFT JOIN `user` u ON u.user_id=s.user_id
AND (s.`desc` LIKE CONCAT('%',#{keyword},'%') OR u.name LIKE CONCAT('%',#{keyword},'%') OR u.major LIKE CONCAT('%',#{keyword},'%') OR CAST(s.snap_id AS CHAR) LIKE CONCAT('%',#{keyword},'%'))
AND s.type=#{type} AND s.status=#{status}

mapper.update:
UPDATE snap
user_id=#{userId}, snap_image=#{snapImage}, `desc`=#{desc}, type=#{type}, status=#{status}, score=#{score},
WHERE snap_id=#{snapId}

mapper.select:
SELECT snap_id,score,ctime FROM snap
WHERE status=0 AND ctime < #{cutoff}
  AND (ctime > #{lastCtime} OR (ctime=#{lastCtime} AND snap_id > #{lastSnapId}))
ORDER BY ctime,snap_id LIMIT #{limit}
